#!/usr/bin/env bash
# From system/: source this file in run_now.sh. It defines jobs; it does not run them.
# NEW batch only. Never point BUDGET_GROUP_FILE at a high-capacity/homogeneous file.
BUDGET_RUN_TAG="${BUDGET_RUN_TAG:-$(date +%Y%m%d_%H%M%S)}"
BUDGET_DATA_ROOT="${BUDGET_DATA_ROOT:-../dataset}"
BUDGET_RUN_ROOT="${BUDGET_RUN_ROOT:-multi_svd_budget_runs/$BUDGET_RUN_TAG}"
BUDGET_GROUP_FILE="${BUDGET_GROUP_FILE:-$BUDGET_RUN_ROOT/shared/budget_K3_first_full_weights.json}"
BUDGET_GROUP_WAIT="${BUDGET_GROUP_WAIT:-7200}"
declare -a COMMANDS=(
"python -u main.py -algo FedMultiGroupProj -data Cifar100 -m Decom_CNN-5-512 -dev cuda -did 0 -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 1 -regular_lamda 1e-3 --target_prox_mu 0 --target_head_l2_lambda 0 --target_head_mode shared --target_local_schedule joint --control_eval_scope all --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$BUDGET_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_svd --multi_svd_ratios 0.299,0.1615,0.114,0.0891,0.0518 --multi_svd_diagnostics 1 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_sizes 7,7,6 --multi_group_mode group_avg_only --multi_group_weight 1.0 --group_softmax_tau 0.20 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_group_file '$BUDGET_GROUP_FILE' --multi_group_wait_seconds $BUDGET_GROUP_WAIT --multi_group_poll_seconds 1 -exp_name budget3_group_avg_only_seed0_gr100 -sfn '$BUDGET_RUN_ROOT/budget3_group_avg_only/checkpoints' --run_log_dir '$BUDGET_RUN_ROOT/budget3_group_avg_only/logs' --h5_result_root '$BUDGET_RUN_ROOT/budget3_group_avg_only/h5' --final_model_root '$BUDGET_RUN_ROOT/budget3_group_avg_only/final_models'"
"python -u main.py -algo FedMultiGroupProj -data Cifar100 -m Decom_CNN-5-512 -dev cuda -did 1 -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 1 -regular_lamda 1e-3 --target_prox_mu 0 --target_head_l2_lambda 0 --target_head_mode shared --target_local_schedule joint --control_eval_scope all --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$BUDGET_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_svd --multi_svd_ratios 0.299,0.1615,0.114,0.0891,0.0518 --multi_svd_diagnostics 1 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_sizes 7,7,6 --multi_group_mode group_projection_softmax --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_group_publish '$BUDGET_GROUP_FILE' -exp_name budget3_group_projection_softmax_seed0_gr100 -sfn '$BUDGET_RUN_ROOT/budget3_group_projection_softmax/checkpoints' --run_log_dir '$BUDGET_RUN_ROOT/budget3_group_projection_softmax/logs' --h5_result_root '$BUDGET_RUN_ROOT/budget3_group_projection_softmax/h5' --final_model_root '$BUDGET_RUN_ROOT/budget3_group_projection_softmax/final_models'"
)
